text:
Use `pg` pool. Key config:

```js
import { Pool } from 'pg';

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: 20,          // max connections (default 10)
  min: 2,           // keep alive when idle
  idleTimeoutMillis: 30_000,    // kill idle conn after 30s
  connectionTimeoutMillis: 5_000, // fail fast if can't connect in 5s

  // Optional: SSL in prod
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : false,
});

// Catch background errors (network drop, DB restart)
pool.on('error', (err, client) => {
  console.error('Idle client error:', err.message);
  // Don't crash — pool auto-removes bad client
});
```

**Query wrapper with timeout:**

```js
async function query(sql, params, timeoutMs = 10_000) {
  const client = await pool.connect();
  try {
    await client.query(`SET statement_timeout = ${timeoutMs}`);
    return await client.query(sql, params);
  } catch (err) {
    // Detect connection-level errors → pool will discard client
    if (err.code === 'ECONNRESET' || err.code === '57P01') {
      client.release(err); // pass err = destroy, not return to pool
    } else {
      client.release();
    }
    throw err;
  } finally {
    // Safety net — release always runs if not already released
    // (double-release is safe in pg)
  }
}
```

Wait — cleaner pattern with guaranteed release:

```js
async function query(sql, params, timeoutMs = 10_000) {
  const client = await pool.connect();
  let released = false;

  const release = (destroy = false) => {
    if (released) return;
    released = true;
    client.release(destroy ? new Error('destroy') : undefined);
  };

  try {
    await client.query(`SET statement_timeout = ${timeoutMs}`);
    const result = await client.query(sql, params);
    release();
    return result;
  } catch (err) {
    const fatal = ['ECONNRESET', 'EPIPE', '57P01'].includes(err.code);
    release(fatal);
    throw err;
  }
}
```

**Graceful shutdown:**

```js
process.on('SIGTERM', async () => {
  await pool.end(); // wait for active queries, then close all
  process.exit(0);
});
```

---

**Key numbers to tune:**

| Setting | Rule of thumb |
|---|---|
| `max` | CPU cores × 2–4, never >100 |
| `min` | 1–5 for warm standby |
| `idleTimeoutMillis` | 30s–5min depending on load pattern |
| `connectionTimeoutMillis` | 2–5s; fail fast beats hanging |
| `statement_timeout` | Per-query; 10s default, lower for APIs |

**Health check** (readiness probe):

```js
export async function dbReady() {
  const res = await pool.query('SELECT 1');
  return res.rowCount === 1;
}
```
